```javascript
const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const N = data[0];
const costs = data.slice(1, 4).sort((a, b) => a - b);

let count = 0;
let total = 0;

for (const cost of costs) {
  if (total + cost <= N) {
    total += cost;
    count++;
  } else {
    break;
  }
}

console.log(count);
